{
  "aggregate_id": "DEF-NRS-484A-285::traffic",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The ridden human-powered devices described by the contract fall within 'other conveyances,' notwithstanding their exclusion from 'vehicle.'"
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "A passenger-carrying motor vehicle satisfies the definition of a device in which persons may be transported, and traffic expressly admits vehicles."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The quoted contract makes every member a pedestrian, so every admitted member carries the included covering class ru.pedestrian."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "The transport vehicles described by the contract fall within the admitted vehicle category, with no exception directed at their commercial mass or licensing characteristics."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "An electric bicycle is a device upon which a person may ride and therefore falls within 'other conveyances' despite the vehicle exception."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The quoted description establishes a conveyance designed to be ridden, which 'other conveyances' admits despite the vehicle exception."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "The vehicle admission reaches emergency vehicles without requiring responding conduct or imposing an exception based on emergency designation."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "A fire-fighting transport vehicle satisfies the vehicle definition, and no exception removes it from traffic."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The quoted moped definition identifies a motor-driven vehicle, which traffic admits and the vehicle exceptions do not remove."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The self-propelled transport vehicles described by the contract satisfy the admitted vehicle definition."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "A motor vehicle ridden astride is a device upon which a person may be transported and falls within the admitted vehicle category."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "The transport vehicles described by the contract are admitted as vehicles, without an exception for official or contracted road service."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "Traffic expressly admits pedestrians, and the posted pedestrian definition reaches the persons described by the contract."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The quoted contract makes every member a pedestrian, so every admitted member carries the included covering class ru.pedestrian."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "Rail conveyances fall within 'other conveyances,' because the stationary-rail exception limits the vehicle definition rather than the broader traffic definition."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "A bus carrying school children satisfies the definition of a device in which persons may be transported, and traffic admits vehicles."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "A passenger vehicle for hire satisfies the transport-device definition and is admitted as a vehicle."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "Both passenger-carrying alternatives in the contract satisfy the vehicle definition and are admitted by 'vehicles.'"
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "The vehicle definition admits devices by which persons or property may be transported or drawn, while 'either singly or together' reaches combinations."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "A public-transit bus is a device in which persons may be transported and falls within the admitted vehicle category."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "A goods-carrying motor vehicle satisfies the definition of a device in which property may be transported, and traffic admits vehicles."
    }
  ]
}

